(()=>{const d=document.querySelector('.az-report-dialog');if(!d)return;const img=d.querySelector('img'),vp=d.querySelector('.az-report-viewport'),zoom=d.querySelector('.az-report-zoom');let trigger=null;document.querySelectorAll('[data-az-report]').forEach(b=>b.addEventListener('click',()=>{trigger=b;img.src=b.dataset.azReport;img.alt=b.querySelector('img').alt;vp.classList.remove('az-zoom');zoom.textContent='Увеличить';zoom.setAttribute('aria-pressed','false');d.showModal();}));d.querySelector('.az-report-close').addEventListener('click',()=>d.close());zoom.addEventListener('click',()=>{const active=vp.classList.toggle('az-zoom');zoom.textContent=active?'По ширине':'Увеличить';zoom.setAttribute('aria-pressed',String(active));});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(trigger)trigger.focus();});})();